import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

// Helper to get allowed origin from environment
const getAllowedOrigin = () => {
  const publicUrl = Deno.env.get('PUBLIC_URL');
  const allowedUrl = Deno.env.get('ALLOWED_ORIGIN');
  return publicUrl || allowedUrl || 'http://localhost:3000';
};

serve(async (req) => {
  // Handle CORS preflight request
  if (req.method === 'OPTIONS') {
    const allowedOrigin = getAllowedOrigin();
    
    return new Response('ok', {
      headers: {
        'Access-Control-Allow-Origin': allowedOrigin,
        'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
        'Access-Control-Allow-Headers':
          'Content-Type, Authorization, apikey, x-client-info',
      },
    });
  }

  try {
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
      { auth: { autoRefreshToken: false, persistSession: false } }
    );

    if (req.method === 'POST') {
      // Create new subscription
      const { email, phone, preferences } = await req.json();

      if (!email && !phone) {
        return new Response(JSON.stringify({ error: 'Email or phone is required' }), {
          status: 400,
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': getAllowedOrigin(),
          },
        });
      }

      const { data, error } = await supabaseAdmin
        .from('subscriptions')
        .insert({
          email,
          phone,
          preferences: preferences || {},
          status: 'ACTIVE',
          created_at: new Date().toISOString()
        })
        .select()
        .single();

      if (error) throw error;

      const allowedOrigin = getAllowedOrigin();

      return new Response(JSON.stringify({ 
        success: true, 
        subscription: data 
      }), {
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': allowedOrigin,
          'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        },
        status: 201,
      });

    } else if (req.method === 'GET') {
      // Get subscriptions (admin only - you might want to add auth check)
      const { data, error } = await supabaseAdmin
        .from('subscriptions')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(1000);

      if (error) throw error;

      const allowedOrigin = getAllowedOrigin();

      return new Response(JSON.stringify({ 
        subscriptions: data || [] 
      }), {
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': allowedOrigin,
          'Access-Control-Allow-Headers': 'Content-Type, Authorization',
        },
        status: 200,
      });
    }

    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': getAllowedOrigin(),
      },
    });

  } catch (error) {
    const allowedOrigin = getAllowedOrigin();
    
    return new Response(JSON.stringify({ error: error.message }), {
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': allowedOrigin,
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      },
      status: 500,
    });
  }
});
